# Find intersection points - cells that have both a diagonal neighbor AND an anti-diagonal neighbor
def find_intersections(positions):
    # Build adjacency lists for each direction
    diag_neighbors = {pos: [] for pos in positions}
    antidig_neighbors = {pos: [] for pos in positions}

    for i, p1 in enumerate(positions):
        for j, p2 in enumerate(positions):
            if i == j:
                continue
            dist_r = abs(p1[0] - p2[0])
            dist_c = abs(p1[1] - p2[1])

            # Same main diagonal (slope +1)
            if dist_r > 0 and dist_r == dist_c:
                diag_neighbors[p1].append(p2)

            # Same anti-diagonal (slope -1)
            if dist_r == dist_c and dist_r != 0:
                antidig_neighbors[p1].append(p2)

    # Find intersections
    intersections = []
    for pos in positions:
        if diag_neighbors[pos] and antidig_neighbors[pos]:
            intersections.append((pos, diag_neighbors[pos], antidig_neighbors[pos]))

    return intersections

